ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'results/nist_auto_vex_20261118';EXP=OUT/'experiment'
def main():
    report=json.loads((EXP/'report.json').read_text());coverage=json.loads((OUT/'coverage.json').read_text());fixture=json.loads((EXP/'fixture_audit.json').read_text())
