    parts.append('</table><p>Exact source spans, source hashes, enum mappings and fix thresholds are available in the <a href="/nist-auto-vex-rules.json">rule registry</a>. Vendor snapshots and rules are pinned; changing either invalidates saved plan hashes and requires rebuilding the questionnaire.</p>')
    parts.append('<h2>Artifacts and reproduction</h2><p><a href="/nist-auto-vex-experiment.json">Full metrics and frozen protocol</a> · <a href="/nist-auto-vex-cases.csv">Every case CSV</a> · <a href="/nist-auto-vex-coverage.json">Entire CVE coverage ledger</a> · <a href="/nist-answer-design.html">All 167 NIST collection domains</a></p><pre>python -X utf8 -B -m unittest discover -s tests -p "test_nist_*.py" -q\npython -X utf8 -B -m tools.item4.run_auto_vex_benchmark\npython -X utf8 -B -m tools.item4.render_auto_vex_report</pre><p>The historical 1,278-case manual-proof benchmark is superseded and is not a result for this automatic engine.</p><pre>'+escape(json.dumps(report['protocol']['sha256'],indent=2))+'</pre></html>')
    (ROOT/'site/nist-auto-vex-method.html').write_text(''.join(parts),encoding='utf-8')
